  static Dictionary<string,object> Plan(string root,Dictionary<string,object> args,OwnedOperationPlans.Proofs p,out Dictionary<string,object> original,out NativeJournal journal){
   original=Read(p,root,args,"closeRequestId","closeReceiptSha256");Need(new[]{"owned_saved_result_closed_unverified","owned_saved_result_close_outcome_unknown"}.Contains((string)original["state"])&&Equals(original["operationId"],args["closeRequestId"])&&Equals(original["nativeProviderQualified"],true)&&Equals(original["contextChangeAttempted"],true)&&Equals(original["cadSaveAttempted"],false)&&Equals(original["geometryMutationAttempted"],false),"Original attempted native saved-result close required.");
   var claim=p.Json(Marker(root,(string)original["targetId"],"result-close-once.json"),(string)original["executionClaimSha256"]);Need(Equals(claim["operationId"],args["closeRequestId"])&&Equals(claim["planSha256"],original["planSha256"])&&Equals(claim["automaticReplayForbidden"],true),"Original result-close claim differs.");
   var plan=p.Json(Artifact(root,"savedresultcloseplans",args["closeRequestId"]),(string)claim["planSha256"]);string[] extras={"schemaVersion","operationId","operation","targetId","copyId","savedResult","targetModelId","before","savedFileHashesBefore","command","fullTopologyEquivalent"};Validate(plan.Where(v=>!extras.Contains(v.Key)).ToDictionary(v=>v.Key,v=>v.Value),false);
   Need(plan.Count==19&&Equals(plan["schemaVersion"],1)&&Equals(plan["operationId"],args["closeRequestId"])&&Equals(plan["targetId"],original["targetId"])&&Equals(plan["operation"],"close_owned_saved_result")&&Equals(plan["command"],OwnedSavedCopyClose.Command)&&Equals(plan["fullTopologyEquivalent"],false),"Frozen saved-result close plan differs.");
   foreach(string k in new[]{"copyId","savedResult","targetModelId","before"})Need(EntitySets.Canonical(original[k])==EntitySets.Canonical(plan[k]),"Original saved-result close dependency differs.");
   journal=NativeJournal.ForVerification(root,(string)args["closeRequestId"],(string)claim["planSha256"]);Need(new[]{"executed_unverified","outcome_unknown"}.Contains(journal.State)&&journal.CommandReturnedDetails!=null&&Equals(journal.CommandReturnedDetails["nativeRequestId"],args["closeRequestId"]),"Authoritative returned saved-result close required; never infer return.");return plan;
  }
  internal static Dictionary<string,object> Verify(string root,string id,Dictionary<string,object> args,OwnedSavedCopyClose.IContext context){
   Validate(args,true);Need(context is OwnedSavedCopyClose.ComContext&&EntitySets.Hex(id,32),"Independent native saved-result close context required.");using(var p=new OwnedOperationPlans.Proofs()){
    Dictionary<string,object> original;NativeJournal journal;var plan=Plan(root,args,p,out original,out journal);using(var source=Source(root,plan,true)){
     Need(Equals(source.Report["targetId"],plan["targetId"])&&Equals(source.Report["copyId"],plan["copyId"])&&EntitySets.Canonical(source.Report["savedResult"])==EntitySets.Canonical(plan["savedResult"])&&Equals(((Dictionary<string,object>)source.Snapshot["model"])["id"],plan["targetModelId"]),"Original saved-result source differs.");
     var observed=Read(p,root,args,"inspectionRequestId","inspectionSha256");var listing=Read(p,root,args,"listingRequestId","listingSha256");DateTime expiry=EntitySets.Expiry(args["expiresUtc"]);Need(EntitySets.Expiry(observed["timestampUtc"])>journal.CommandReturnedUtc&&EntitySets.Expiry(listing["timestampUtc"])>journal.CommandReturnedUtc&&expiry<=EntitySets.Expiry(observed["timestampUtc"]).AddSeconds(300)&&expiry<=EntitySets.Expiry(listing["timestampUtc"]).AddSeconds(300),"Fresh separate post-close observations required.");
     OwnedSavedCopyClose.CheckAfter((Dictionary<string,object>)plan["before"],listing,(int)plan["targetModelId"]);if(original.ContainsKey("after"))Need(DocumentBindings.WindowDigest(listing)==DocumentBindings.WindowDigest((Dictionary<string,object>)original["after"]),"Returned saved-result window state changed.");
     for(int i=0;i<2;i++){Need(DocumentBindings.WindowDigest(context.Windows())==DocumentBindings.WindowDigest(listing),"Fresh post-close windows changed.");EntitySets.CheckObserved(observed,context.Observation(),new int[0][],expiry,DateTime.UtcNow);context.ConfirmDocument();}source.Recheck();Need(OwnedSavedCopyClose.SavedHashesEqual(plan["savedFileHashesBefore"],WorkingCopyOpen.SavedHashes((Dictionary<string,object>)plan["before"])),"Saved files changed after result close.");
     string fence=Marker(root,(string)plan["targetId"],"result-close-fence.json");var marker=NativeJournal.VerifiedJson(fence,(string)original["executionFenceSha256"],65536);Need(Equals(marker["operationId"],args["closeRequestId"])&&Equals(marker["planSha256"],original["planSha256"])&&Equals(marker["targetId"],plan["targetId"])&&DateTime.UtcNow<expiry,"Matching result-close fence/lifetime required.");
     var evidence=new[]{new Dictionary<string,object>{{"requestId",args["closeRequestId"]},{"sha256",args["closeReceiptSha256"]}},new Dictionary<string,object>{{"requestId",args["inspectionRequestId"]},{"sha256",args["inspectionSha256"]}},new Dictionary<string,object>{{"requestId",args["listingRequestId"]},{"sha256",args["listingSha256"]}}};journal.Append("succeeded_verified",new Dictionary<string,object>{{"evidence",evidence},{"closedModelId",plan["targetModelId"]},{"noCommandReplay",true}});NativeJournal.VerifiedJson(fence,(string)original["executionFenceSha256"],65536);File.Delete(fence);
     var result=Base("owned_saved_result_close_verified",id);result["verificationId"]=id;result["operationId"]=args["closeRequestId"];foreach(string k in new[]{"targetId","copyId","savedResult","targetModelId"})result[k]=plan[k];result["planSha256"]=original["planSha256"];result["nativeProviderQualified"]=true;result["savedFilesUnchanged"]=true;result["noCommandReplay"]=true;result["recordedJournalState"]=journal.State;result["timestampUtc"]=DateTime.UtcNow.ToString("o");return result;
    }
   }
  }
  internal static Dictionary<string,object> Run(string id,string recipe,Dictionary<string,object> args){
   bool verify=recipe==Recipes[1],connected=false;try{var cfg=Program.ReadConfig();Need(cfg.IsGeneralCore&&cfg.ownedSavedResultCloseExperimental&&Recipes.Contains(recipe),"Owned saved-result close disabled.");Validate(args,verify);Directory.CreateDirectory(Path.Combine(Program.Root,"operations"));using(var serial=new FileStream(Path.Combine(Program.Root,"operations","executor.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){
