   }}catch(Exception e){var result=Base(verify?"owned_saved_result_close_verification_rejected":"owned_saved_result_close_rejected",id);result["error"]=e.Message;result["powerShapeConnectionAttempted"]=connected;result["timestampUtc"]=DateTime.UtcNow.ToString("o");return result;}
  }
